# Rewrite cleanly
def get_connected_regions(grid):
    """Get connected regions using 8-connectivity (including diagonals)"""
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    regions = []

    for start_r in range(rows):
        for start_c in range(cols):
            if grid[start_r][start_c] == 8 and not visited[start_r][start_c]:
                cells = []
                to_visit = [(start_r, start_c)]
                visited[start_r][start_c] = True

                while to_visit:
                    r, c = to_visit.pop()
                    cells.append((r, c))

                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if not visited[nr][nc] and grid[nr][nc] == 8:
                                    visited[nr][nc] = True
                                    to_visit.append((nr, nc))

                regions.append(cells)

    return regions

