def local_density(grid, r, c, radius=1):
    """Count 8s within radius of (r,c)"""
    count = 0
    for dr in range(-radius, radius+1):
        for dc in range(-radius, radius+1):
            if dr == 0 and dc == 0:
                if grid[r+dr][c+dc] == 8:
                    count += 1
            else:
                nr, nc = r + dr, c + dc
                if nr < 0 or nr >= len(grid) or nc < 0 or nc >= len(grid[0]):
                    continue
                if grid[nr][nc] == 8:
                    count += 1
    return count

