def get_3x3_window(grid, r, c):
    """Get 3x3 window centered at (r,c), return flat tuple of 9 values"""
    result = []
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                result.append(grid[nr][nc])
            else:
                result.append(0)  # Padding with 0 for out-of-bounds
    return tuple(result)

