def manhattan_distance(grid, target_r, target_c, start_r, start_c):
    """Manhattan distance between two points"""
    return abs(target_r - start_r) + abs(target_c - start_c)

def min_manhattan_to_zero(grid, r, c):
    """Find minimum Manhattan distance from (r,c) to any 0 cell"""
    min_d = float('inf')
    for rr in range(len(grid)):
        for cc in range(len(grid[0])):
            if grid[rr][cc] == 0:
                d = manhattan_distance(grid, rr, cc, r, c)
                if d < min_d:
                    min_d = d
    return min_d

