def get_quadrant(r, c, rows, cols):
    """Return quadrant number: 0=TL, 1=TR, 2=BL, 3=BR"""
    mid_r = rows // 2
    mid_c = cols // 2
    if r < mid_r and c < mid_c:
        return 0  # Top-left
    elif r < mid_r and c >= mid_c:
        return 1  # Top-right
    elif r >= mid_r and c < mid_c:
        return 2  # Bottom-left
    else:
        return 3  # Bottom-right

